<template><select class="sc-input" data-semantic-component="ScSelect" data-semantic-layer="primitive" :data-size="size" :data-status="status" :data-readonly="readonly || undefined" :value="modelValue" :disabled="disabled" :aria-disabled="disabled || undefined" :aria-readonly="readonly || undefined" :aria-required="required || undefined" :aria-invalid="invalid || status === 'error' || undefined" :aria-describedby="describedBy" @change="onChange"><slot /></select></template>
<script setup lang="ts">import type { ScPrimitiveSize, ScPrimitiveStatus } from './primitiveAdapter'; const props=withDefaults(defineProps<{ modelValue:string|number; size?:ScPrimitiveSize; status?:ScPrimitiveStatus; disabled?:boolean; readonly?:boolean; required?:boolean; invalid?:boolean; describedBy?:string }>(),{size:'medium',status:'default',describedBy:undefined}); const emit=defineEmits<{ 'update:modelValue':[value:string]; change:[value:string] }>(); function onChange(event:Event){const target=event.target as HTMLSelectElement;if(props.readonly){target.value=String(props.modelValue);return;}emit('update:modelValue',target.value);emit('change',target.value);}</script>
